using System;
using System.Collections.Generic;
using System.Globalization;
using System.Text.Json;

Func<Dictionary<string, JsonElement>, string> fmt = p =>
{
    var id = p["id"].GetInt32();
    var name = p["name"].GetString()!;
    var price = p["price"].GetDouble();
    return $"{{{id} {name} {price.ToString("F2", CultureInfo.InvariantCulture)}}}";
};

var original = new Dictionary<string, object>
{
    ["id"] = 1,
    ["name"] = "Laptop",
    ["price"] = 999.99,
};
var opts = new JsonSerializerOptions { PropertyNamingPolicy = JsonNamingPolicy.CamelCase };
var json = JsonSerializer.Serialize(original, opts);
var origDict = JsonSerializer.Deserialize<Dictionary<string, JsonElement>>(json, opts)!;
var recovered = JsonSerializer.Deserialize<Dictionary<string, JsonElement>>(json, opts)!;
Console.WriteLine($"Original: {fmt(origDict)}");
Console.WriteLine($"Recovered: {fmt(recovered)}");

using System.Collections.Generic;
using System.Text.Json;

var addr = new Dictionary<string, object>
{
    ["Street"] = "123 Main St",
    ["City"] = "Springfield",
};
var user = new Dictionary<string, object>
{
    ["Name"] = "Alice",
    ["Address"] = addr,
};
Console.WriteLine(JsonSerializer.Serialize(user));

using System.Collections.Generic;
using System.Text.Json;

var people = new List<Dictionary<string, object>>
{
    new() { ["Name"] = "Alice", ["Age"] = 30 },
    new() { ["Name"] = "Bob", ["Age"] = 25 },
};
Console.WriteLine(JsonSerializer.Serialize(people));

using System.Text.Json;

var json = "{\"level\":\"info\",\"data\":{\"action\":\"login\",\"user\":\"alice\"}}";
using var doc = JsonDocument.Parse(json);
var root = doc.RootElement;
Console.WriteLine(root.GetProperty("level").GetString());
Console.WriteLine(root.GetProperty("data").GetRawText());

using System.Text.Json;

var json = "[{\"Name\":\"Alice\",\"Age\":30},{\"Name\":\"Bob\",\"Age\":25}]";
using var doc = JsonDocument.Parse(json);
foreach (var el in doc.RootElement.EnumerateArray())
{
    var name = el.GetProperty("Name").GetString();
    var age = el.GetProperty("Age").GetInt32();
    Console.WriteLine($"{name} {age}");
}
